CREATE TABLE "marketplace_listings" ("id" TEXT NOT NULL,"organizationId" TEXT NOT NULL,"title" TEXT NOT NULL,"description" TEXT NOT NULL,"category" TEXT NOT NULL,"listingType" TEXT NOT NULL,"status" TEXT NOT NULL DEFAULT 'DRAFT',"city" TEXT NOT NULL,"canton" TEXT,"price" INTEGER,"date" TIMESTAMP(3),"details" JSONB,"imageUrls" TEXT[] DEFAULT ARRAY[]::TEXT[],"views" INTEGER NOT NULL DEFAULT 0,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,"publishedAt" TIMESTAMP(3),"expiresAt" TIMESTAMP(3),CONSTRAINT "marketplace_listings_pkey" PRIMARY KEY ("id"));
CREATE TABLE "marketplace_inquiries" ("id" TEXT NOT NULL,"listingId" TEXT NOT NULL,"senderName" TEXT NOT NULL,"senderEmail" TEXT NOT NULL,"message" TEXT NOT NULL,"reply" TEXT,"repliedAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "marketplace_inquiries_pkey" PRIMARY KEY ("id"));
CREATE INDEX "marketplace_listings_status_category_createdAt_idx" ON "marketplace_listings"("status","category","createdAt");
CREATE INDEX "marketplace_listings_organizationId_status_idx" ON "marketplace_listings"("organizationId","status");
CREATE INDEX "marketplace_inquiries_listingId_createdAt_idx" ON "marketplace_inquiries"("listingId","createdAt");
ALTER TABLE "marketplace_listings" ADD CONSTRAINT "marketplace_listings_organizationId_fkey" FOREIGN KEY ("organizationId") REFERENCES "organizations"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "marketplace_inquiries" ADD CONSTRAINT "marketplace_inquiries_listingId_fkey" FOREIGN KEY ("listingId") REFERENCES "marketplace_listings"("id") ON DELETE CASCADE ON UPDATE CASCADE;